def topological_sort(nodes, edges):
    def validate_and_build():
        node_set = set(nodes)
        for source, destination in edges:
            if source not in node_set:
                raise ValueError("edge source not in nodes: %r" % (source,))
            if destination not in node_set:
                raise ValueError("edge destination not in nodes: %r" % (destination,))
        adjacency = {node: set() for node in nodes}
        for source, destination in edges:
            adjacency[source].add(destination)
        return node_set, adjacency

    node_set, adjacency = validate_and_build()

    in_degree = {node: 0 for node in nodes}
    for source in adjacency:
        for destination in adjacency[source]:
            in_degree[destination] += 1

    available = sorted(node for node in nodes if in_degree[node] == 0)
    ordering = []
    while available:
        current = available.pop(0)
        ordering.append(current)
        for destination in sorted(adjacency[current]):
            in_degree[destination] -= 1
            if in_degree[destination] == 0:
                available.append(destination)
        available.sort()

    if len(ordering) != len(node_set):
        raise ValueError("cycle detected")

    return ordering
